script.lang:
INSERT INTO amp_modules_visibility (id, name, description, haslevel, parent) SELECT nextval('amp_modules_visibility_seq'), '/Activity Form/M&E/ME Item/Actual Values', NULL, true, (SELECT id FROM amp_modules_visibility WHERE name = '/Activity Form/M&E/ME Item') WHERE EXISTS (SELECT 1 FROM amp_modules_visibility WHERE name = '/Activity Form/M&E/ME Item') AND NOT EXISTS (SELECT 1 FROM amp_modules_visibility WHERE name = '/Activity Form/M&E/ME Item/Actual Values');
INSERT INTO amp_modules_templates (module, template) SELECT (SELECT id FROM amp_modules_visibility WHERE name = '/Activity Form/M&E/ME Item/Actual Values'), tv.id FROM amp_templates_visibility tv WHERE EXISTS (SELECT 1 FROM amp_modules_templates mt WHERE mt.template = tv.id AND mt.module = (SELECT id FROM amp_modules_visibility WHERE name = '/Activity Form/M&E/ME Item')) AND NOT EXISTS (SELECT 1 FROM amp_modules_templates mt WHERE mt.template = tv.id AND mt.module = (SELECT id FROM amp_modules_visibility WHERE name = '/Activity Form/M&E/ME Item/Actual Values'));
